negativeExample:
package test;

import org.eclipse.core.resources.IProject;
import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IProgressMonitor;
import org.eclipse.core.runtime.NullProgressMonitor;
import org.eclipse.core.runtime.SubProgressMonitor;

public class TestClass {
    public void openProjectWithFlags(IProject project, IProgressMonitor monitor) {
        try {
            // Should not match if other flags are present or no progress monitor
            project.open(IResource.FORCE | IResource.KEEP_HISTORY, new SubProgressMonitor(monitor, 1));
            project.open(null); // Does not match SubProgressMonitor argument
            project.open(IResource.BACKGROUND_REFRESH, null); // Already has the flag and different argument
        } catch (CoreException e) {
            e.printStackTrace();
        }
    }
}
